from rdkit import Chem
from rdkit.Chem import AllChem
from scipy.spatial.transform import Rotation
import numpy as np
mol=Chem.AddHs(Chem.MolFromSmiles('P(C(C)C)(C(C)C)C(C)C'))
params=AllChem.ETKDGv3(); params.randomSeed=51431
cs=AllChem.EmbedMultipleConfs(mol,numConfs=30,params=params)
vals=AllChem.MMFFOptimizeMoleculeConfs(mol,maxIters=400)
i=min(range(len(vals)), key=lambda x:vals[x][1]); conf=mol.GetConformer(int(i))
pos=np.array(conf.GetPositions()); els=[a.GetSymbol() for a in mol.GetAtoms()]
print('ligand atoms', len(els),'energy',vals[i][1]); print('P indices', [a.GetIdx() for a in mol.GetAtoms() if a.GetSymbol()=='P'])
# ligand P index 0; + direction is P->average attached carbon; orient toward exterior
pos-=pos[0]; vec=np.mean(pos[[a.GetIdx() for a in mol.GetAtomWithIdx(0).GetNeighbors()]],axis=0); vec/=np.linalg.norm(vec)
def rotation_align(v,w):
 cross=np.cross(v,w); s=np.linalg.norm(cross); c=np.dot(v,w)
 if s<1e-10:
  if c>0: return np.eye(3)
  u=np.cross(v,[1,0,0]); u/=np.linalg.norm(u)
  return Rotation.from_rotvec(np.pi*u).as_matrix()
 return Rotation.from_rotvec(np.arctan2(s,c)*cross/s).as_matrix()
xyz=[('Ir',np.array([0.,0.,0.])),('Cl',np.array([2.42,0,0])),('Cl',np.array([-2.42,0,0])),('H',np.array([0,1.59,0])),('H',np.array([0,-1.59,0]))]
for ax,theta in [(1,15),(-1,75)]:
 q=rotation_align(vec,np.array([0,0,ax],dtype=float)); spin=Rotation.from_euler('z',theta,degrees=True).as_matrix()
 p=pos@q.T@spin.T+np.array([0.,0.,ax*2.36])
 for el,coord in zip(els,p):xyz.append((el,coord))
with open('initial.xyz','w') as f:
 f.write(f'{len(xyz)}\ntrans-[IrH2Cl2(P(iPr)3)2], unoptimized\n')
 for e,p in xyz:f.write(f'{e:2} {p[0]: .8f} {p[1]: .8f} {p[2]: .8f}\n')
print('xyz atoms',len(xyz))
for k in range(len(xyz)):
 if xyz[k][0] != 'H':
